-- Fifth batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('6addf192-d647-5bc5-acdb-8584614998ce', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). В профазе хроматин конденсируется, формируется веретено; в прометафазе разрушается ядерная оболочка и микротрубочки связываются с кинетохорами. В метафазе хромосомы выстраиваются на экваторе, в анафазе сестринские хроматиды расходятся к полюсам, в телофазе формируются дочерние ядра; цитокинез разделяет цитоплазму. Регуляция включает циклины и циклин-зависимые киназы, контрольные точки повреждения ДНК и прикрепления хромосом; нарушения могут приводить к анеуплоидии.'),
  ('facb477c-d8f6-5fb1-a7da-7f5613c3fb25', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Клеточная оболочка включает плазматическую мембрану с липидным бислоем, белками и углеводами. Она обеспечивает барьер, транспорт, рецепцию и межклеточное распознавание. Контакты: плотные соединения ограничивают парацеллюлярный транспорт; адгезивные контакты и десмосомы механически связывают клетки; щелевые соединения проводят ионы и малые молекулы; полудесмосомы прикрепляют эпителий к базальной мембране. Набор контактов зависит от функции ткани.'),
  ('17091069-c8e2-5285-b524-a3f2d1f3fe3c', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Лизосомы — мембранные органеллы с кислой средой и гидролитическими ферментами для внутриклеточного переваривания эндоцитированного материала и повреждённых органелл. Пероксисомы содержат оксидазы и каталазу, участвуют в β-окислении очень длинноцепочечных жирных кислот и обезвреживании перекиси водорода. Лизосомные ферменты работают оптимально при низком pH; пероксисомы не имеют собственного генома и делятся при росте/делении органелл.'),
  ('5f31b7e0-f9d7-58b0-8a6b-90878b32d9c9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Клеточные включения — непостоянные продукты обмена или запасные вещества, обычно не обладающие собственной мембраной. Различают трофические (гликоген, липиды), секреторные, экскреторные и пигментные включения. Их выявляют специальными окрасками и гистохимическими реакциями: липиды — Суданом/осмиевой кислотой, гликоген — реакцией PAS, некоторые пигменты — специфическими реакциями. Гиалоплазма — водная коллоидная среда цитоплазмы, в которой протекают метаболические реакции и перемещаются молекулы и органеллы.'),
  ('680e2462-2874-522c-89cd-ac343540a557', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Синтез секретируемого белка начинается на рибосомах гранулярной ЭПС, полипептид поступает в её просвет, сворачивается и проходит контроль качества, затем в пузырьках направляется в комплекс Гольджи для модификации и сортировки. Секреторные гранулы доставляются к мембране и выделяют содержимое экзоцитозом. Липиды синтезируются преимущественно в гладкой ЭПС; митохондрии обеспечивают АТФ, цитоскелет и моторные белки перемещают везикулы, лизосомы разрушают ненужный материал.'),
  ('aa7553f8-f5e3-54d9-a027-62189db81baa', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Клеточный цикл включает G1 (рост), S (репликация ДНК), G2 (подготовка к делению) и M-фазу (митоз и цитокинез); некоторые клетки входят в состояние G0. Контрольные точки проверяют целостность ДНК и правильность прикрепления хромосом к веретену. Апоптоз — регулируемая программируемая гибель клетки с активацией каспаз, конденсацией хроматина и образованием апоптотических телец без выраженного воспаления. Он необходим для развития, обновления тканей и удаления повреждённых клеток.'),
  ('4280f9a5-dee9-5b7e-89a7-3280142f64d5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). При митозе хромосомы конденсируются, выстраиваются на метафазной пластинке, сестринские хроматиды расходятся, а ядра восстанавливаются в телофазе. Циклин-зависимые киназы управляют переходами цикла; контрольные точки задерживают деление при повреждении ДНК или неправильном прикреплении хромосом. Митоз необходим для роста, регенерации и бесполого размножения клеток; ошибки сегрегации приводят к геномной нестабильности.'),
  ('4158bd5f-6893-504a-bc77-0cf79a0ab75b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Митоз включает профазу, прометафазу, метафазу, анафазу и телофазу; затем обычно следует цитокинез. Хромосомы конденсируются, прикрепляются к веретену, выстраиваются по экватору и расходятся к полюсам, после чего восстанавливаются ядра. Контроль деления обеспечивают циклин-CDK-комплексы, контрольная точка G1/S, проверка репликации ДНК и контроль прикрепления кинетохоров. Митоз обеспечивает рост, обновление и сохранение числа хромосом.'),
  ('64c9f529-bc8b-54bb-8943-e8338015fdfa', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Дифференцировка — приобретение клеткой специализированного строения и функций через изменение экспрессии генов. Она регулируется транскрипционными факторами, эпигенетическими механизмами, сигналами соседних клеток, гормонами и внеклеточным матриксом. Дифферон — последовательность стадий развития клеточной линии от стволовой/прогениторной клетки к зрелой форме. Примеры: кроветворные диффероны эритроцитов и гранулоцитов; в эпителии кишечника стволовые клетки дают энтероциты и секреторные клетки.'),
  ('626813aa-50c0-5675-9352-397f72024ab9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Биологические мембраны состоят из липидного бислоя, белков и углеводных компонентов. Фосфолипиды формируют барьер, холестерин регулирует текучесть, белки работают как каналы, переносчики, рецепторы, ферменты и элементы цитоскелетного прикрепления. Мембраны разделяют компартменты, обеспечивают транспорт веществ, преобразование сигналов, межклеточные контакты и поддержание потенциала. Гликокаликс участвует в защите и распознавании клеток.'),
  ('da0f7d5b-6d5a-52b5-b3af-4a458528c2f7', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гистология изучает микроскопическое строение клеток, тканей и органов и связывает их структуру с функцией. Для медицины важны морфологическая диагностика опухолей и воспаления, цитология мазков, биопсия, иммуногистохимия, электронная микроскопия, оценка регенерации и патологии. Эмбриология помогает понимать врождённые пороки и развитие органов; тканевые технологии и клеточные культуры применяются в исследованиях и отдельных лечебных подходах. Методы выбирают по диагностической задаче и ограничениям образца.'),
  ('7a673342-c272-59cf-a472-7b10f2ff765c', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Клеточная теория утверждает, что все живые организмы состоят из клеток и продуктов их жизнедеятельности; клетка — основная структурная и функциональная единица; новые клетки возникают из предшествующих клеток; клетки имеют общие принципы хранения и реализации наследственной информации. Современная теория учитывает специализацию клеток, передачу генетической информации и межклеточные взаимодействия. Для медицины она лежит в основе понимания опухолевого роста, наследственных болезней, иммунитета и регенерации.'),
  ('48b960e1-d1ac-5bcb-b420-1dfd35b97413', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Комплекс Гольджи состоит из уплощённых цистерн и пузырьков; он модифицирует белки и липиды, сортирует их и направляет к мембране, секреторным гранулам или лизосомам. Митохондрии имеют наружную и внутреннюю мембраны, кристы, матрикс, собственную ДНК и рибосомы; обеспечивают синтез АТФ при окислительном фосфорилировании и участвуют в регуляции апоптоза. Их количество особенно велико в клетках с высокой энергетической потребностью.'),
  ('41726f0b-2cb3-54e2-888f-eab046e0d9fe', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эукариотическая клетка имеет плазматическую мембрану, цитоплазму с органеллами и ядро с генетическим материалом. Ядро регулирует экспрессию генов; рибосомы синтезируют белок, гранулярная ЭПС производит секретируемые и мембранные белки, комплекс Гольджи модифицирует и сортирует их, митохондрии синтезируют АТФ, лизосомы расщепляют материал, цитоскелет обеспечивает форму и транспорт. Клетка — структурно-функциональная единица ткани, но её свойства зависят от взаимодействия с соседними клетками и матриксом.'),
  ('87e55f90-e963-5de3-96a5-c10ff664e6f6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Симпласт — многоядерная цитоплазматическая структура, возникающая при слиянии клеток; пример — скелетное мышечное волокно. Межклеточное вещество образовано клетками ткани и включает волокна и основное вещество; в соединительной ткани его много, в эпителии мало. Оно обеспечивает механическую опору, диффузию, адгезию и сигнальную регуляцию. Межклеточное вещество нельзя путать с межклеточным пространством: это организованный внеклеточный матрикс.'),
  ('1423a4dc-273f-5349-9e43-b06aed0410d1', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Плазматическая мембрана описывается жидкостно-мозаичной моделью: фосфолипидный бислой с холестерином, интегральными и периферическими белками и углеводными цепями гликопротеинов/гликолипидов снаружи. Мембрана обеспечивает избирательную проницаемость, транспорт, рецепцию сигналов, межклеточное распознавание, адгезию и поддержание электрохимических градиентов. Транспорт бывает пассивным, активным и везикулярным; состав мембраны динамичен.'),
  ('75af6648-95d7-53bf-904f-1de18f21e934', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Цитоплазма включает гиалоплазму, органеллы и включения. Органеллы бывают мембранными (ЭПС, комплекс Гольджи, митохондрии, лизосомы, пероксисомы) и немембранными (рибосомы, центриоли, элементы цитоскелета). Гранулярная ЭПС синтезирует белки для секреции и мембран, гладкая ЭПС участвует в синтезе липидов, детоксикации и запасании Ca2+. Органеллы действуют согласованно: синтез, модификация, транспорт и деградация веществ образуют единый клеточный метаболизм.'),
  ('4a21a045-eac1-554c-8ffe-d3d8635eefea', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Включения классифицируют как трофические (гликоген, жир), секреторные гранулы, экскреторные продукты и пигменты (меланин, липофусцин, гемосидерин). Они отражают функциональное состояние клетки и могут временно накапливаться или удаляться. Для выявления используют специальные красители и гистохимические методы; например, PAS-реакция выявляет богатые углеводами структуры, а липиды лучше сохраняются в замороженных срезах и окрашиваются липофильными красителями.'),
  ('b2490950-9d13-53e4-821a-561cfedbfca9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Стволовые клетки способны к самообновлению и образованию дифференцированных потомков. Дифференцировка регулируется генетическими программами, сигналами ниши и факторами роста. Регенерация бывает физиологической (обычное обновление) и репаративной (после повреждения); восстановление возможно путём реституции либо замещения рубцовой тканью. Высокий потенциал характерен для эпителия и кроветворной ткани, ограниченный — для миокарда и нейронов ЦНС.'),
  ('e0642516-4f41-5cda-99c8-e5b74599bb04', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эффекторные нервные окончания передают сигнал мышцам и железам. В скелетной мышце нервно-мышечный синапс имеет пресинаптическое окончание мотонейрона, щель с базальной мембраной и постсинаптические складки сарколеммы с никотиновыми рецепторами ацетилхолина; передача быстрая и обычно возбуждающая. В гладкой мышце автономные аксоны имеют варикозные утолщения, медиатор диффундирует к нескольким клеткам, а ответ регулируется также гормонами и локальными факторами.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
